python3 - <<'E'
p='src/Storefront/Pricing/PriceCache.cs'
s=open(p).read()
s=s.replace("""        get
        {
            lock (Gate)
            {
                return _lookups;
            }
        }
""","""        get => Interlocked.Read(ref _lookups);
""")
